# Agregamos números, letras, espacios, paréntesis, guiones y TODOS los caracteres con acentos
regex_nombres = r'([\w\s\(\)\-áéíóúÁÉÍÓÚñÑ]+?):\s*(.*?)(?=(?:[\w\s\(\)\-áéíóúÁÉÍÓÚñÑ]+?:)|$)'

datos = {}
anexo_pattern = re.compile(r'(ANEXO [IXV]+) - ([A-Z \xcd\xd1\xd3\xc9\xc1]+):')
anexos_matches = list(anexo_pattern.finditer(texto))

for i, match in enumerate(anexos_matches):
    anexo_id = match.group(1)
    localidad = match.group(2).title()
    
    start_idx = match.end()
    end_idx = anexos_matches[i+1].start() if i + 1 < len(anexos_matches) else len(texto)
    barrios_str = texto[start_idx:end_idx]
    
    barrio_matches = list(re.finditer(regex_nombres, barrios_str))
    
    barrios = {}
    for bm in barrio_matches:
        bname = bm.group(1).strip()
        bname = re.sub(r'^\.\s*', '', bname).strip()
        bdesc = bm.group(2).strip()
        if bname and bdesc:
            barrios[bname] = bdesc
            
    datos[anexo_id] = {
        "localidad": localidad,
        "barrios": barrios
    }

# Read procesador_barrios_13906.py
with open('procesador_barrios_13906.py', 'r', encoding='utf-8') as f:
    content = f.read()

start_marker = "DATOS_ORDENANZA = {"
end_marker = "}\n\n# ==============================================================================\n# MOTOR GEOCODIFICADOR ESTRATÉGICO"

if start_marker in content and end_marker in content:
    pre = content[:content.find(start_marker)]
    post = content[content.find(end_marker) + 1:]
    new_dict_str = "DATOS_ORDENANZA = " + json.dumps(datos, ensure_ascii=False, indent=4)
    with open('procesador_barrios_13906.py', 'w', encoding='utf-8') as f:
        f.write(pre + new_dict_str + post)
    print("Sustitucion completada exitosamente.")
else:
    print("No se encontraron los marcadores")
